-- Migración: la tienda deja de ser obligatoria al crear un vendedor (credencial
-- global válida en cualquier tienda hasta que se le asigne una). Idempotente:
-- no falla si la columna ya es nullable.
ALTER TABLE vendedores ALTER COLUMN tienda_id DROP NOT NULL;

-- Migración: usuario del vendedor (para BDs creadas antes de agregar la columna).
ALTER TABLE vendedores ADD COLUMN IF NOT EXISTS usuario TEXT;
